{
  "project": "simd-json",
  "audited_path": "src/",
  "bugs": [
    {
      "kind": "wrong-behavior",
      "summary": "Derived struct deserialization fails to skip unknown object-valued or array-valued fields. Because ignored_any is forwarded to deserialize_any, only the container header is consumed and nested entries are treated as subsequent outer fields, causing a later required field to be lost or misread.",
      "location": [
        "src/serde/de.rs:33",
        "src/serde/de.rs:352"
      ],
      "match_rule": "A report must claim that ordinary Serde unknown-field handling leaves the contents of an ignored nested object or array unread and consequently misaligns later fields of a derived struct.",
      "confirmed_at_baseline": "reproduced",
      "caveat": "",
      "id": "K001"
    },
    {
      "kind": "wrong-behavior",
      "summary": "Tape Value get_array, get_object, try_get_array and try_get_object slice the tape one node short, losing the last element of a nested container.",
      "location": [
        "src/value/tape/trait_impls.rs:425",
        "src/value/tape/trait_impls.rs:454",
        "src/value/tape/trait_impls.rs:487",
        "src/value/tape/trait_impls.rs:519"
      ],
      "confirmed_at_baseline": "reproduced",
      "match_rule": "Names the off-by-one slice idx..idx+count in the tape shortcut accessors (container header plus count nodes), dropping the last element or leaving an empty slice that later panics on empty containers.",
      "caveat": "Kept as wrong-behavior, but the panics on empty containers are a crash from valid input on the same defect; a finding that reports only that panic should score here. Shared code.",
      "id": "K002"
    },
    {
      "kind": "wrong-behavior",
      "summary": "Long decimals are corrupted because a byte value is used as an index when digit_count is corrected.",
      "location": [
        "src/numberparse/correct.rs:168",
        "src/numberparse/correct.rs:172"
      ],
      "confirmed_at_baseline": "reproduced",
      "match_rule": "Names `start_digits = get!(buf, start) as usize` in the float path, which stores the byte at start rather than the offset, so the leading-zero digit_count correction is wrong and long decimals get a wrong value.",
      "caveat": "Listed as a possible crash, but it gives a wrong value and did not panic in any run. Shared code.",
      "id": "K003"
    },
    {
      "kind": "wrong-behavior",
      "summary": "Huge exponents wrap through `as i32` and give wrong finite numbers, while valid very long exponents are rejected.",
      "location": [
        "src/numberparse/correct.rs:156",
        "src/numberparse/correct.rs:186"
      ],
      "confirmed_at_baseline": "reproduced",
      "match_rule": "Names narrowing the accumulated i64 exponent with `as i32` (wrapping into range and giving a wrong finite value) or the error on exponents past 2^32 rejecting valid numbers, in the default number parser.",
      "caveat": "Upstream fix is co-authored by Claude. Shared code.",
      "id": "K004"
    },
    {
      "kind": "wrong-behavior",
      "summary": "A NUL byte counts as structural-or-whitespace, so a number followed by NUL is accepted.",
      "location": [
        "src/charutils.rs:14",
        "src/numberparse/correct.rs:180",
        "src/numberparse/correct.rs:192",
        "src/lib.rs:798"
      ],
      "confirmed_at_baseline": "reproduced",
      "match_rule": "Names the STRUCTURAL_OR_WHITESPACE tables treating byte 0 as a valid terminator (tied to zero padding of the input buffer), so number parsing accepts an embedded NUL after a number.",
      "caveat": "Listed as a possible crash, but it does not panic. The tag has a test that asserts this behaviour with a todo comment, so upstream knew. Shared code.",
      "id": "K005"
    },
    {
      "kind": "wrong-behavior",
      "summary": "Fixed-length serde targets leave unread array elements on the tape, which are then read as later values.",
      "location": [
        "src/serde/de.rs:33",
        "src/serde/de.rs:34",
        "src/serde/de.rs:240",
        "src/serde/de.rs:433"
      ],
      "confirmed_at_baseline": "reproduced",
      "match_rule": "Names the serde array path handing a visitor CommaSeparated without checking afterward that all elements were consumed, so surplus elements shift into later fields of a tuple, array or struct target.",
      "caveat": "Upstream fix is co-authored by Claude. Shared code.",
      "id": "K006"
    },
    {
      "kind": "wrong-behavior",
      "summary": "A lone high surrogate such as \"\\ud800\" parses as NUL (U+0000) instead of returning an error.",
      "location": [
        "src/stringparse.rs:61",
        "src/stringparse.rs:72"
      ],
      "confirmed_at_baseline": "reproduced",
      "match_rule": "Names get_unicode_codepoint returning Ok((0, _)) for a high surrogate without a following low surrogate, a leftover failure sentinel that callers now take as code point 0, silently decoding it as NUL.",
      "caveat": "RFC 8259 section 8.2 only says lone surrogates give unpredictable behaviour; the wrong part is silent NUL where the crate rejects the low-surrogate twin. Upstream fix is co-authored by Claude. Parse_str differs per backend but this function is shared; run on NEON. `\"\\ud800\\uzzzz\"` already errored here on NEON through another check.",
      "id": "K007"
    },
    {
      "kind": "wrong-behavior",
      "summary": "Serializing an empty Vec with simd_json::to_string emits only an opening bracket. SerializeSeq::end returns successfully while first is still true, leaving the empty array unterminated; nesting the empty Vec also produces malformed JSON.",
      "location": [
        "src/serde/se.rs:96"
      ],
      "match_rule": "A report must identify empty known-length sequences, such as Vec::<u8>::new(), as emitting an unterminated array because SerializeSeq::end skips the closing bracket when first is true.",
      "confirmed_at_baseline": "reproduced",
      "caveat": "",
      "id": "K008"
    }
  ]
}

